import { useMemo, useState } from 'react'
import { createRoot } from 'react-dom/client'
import {
  AlertTriangle, ArrowLeft, ArrowRight, BadgeCheck, BellRing, CalendarDays,
  Check, CheckCircle2, ChevronDown, ChevronLeft, ChevronRight, CircleAlert,
  Clock3, Download, FileText, Filter, HeartPulse, Landmark, MoreHorizontal,
  Pencil, Plus, Search, Settings2, ShieldAlert, SlidersHorizontal, Trash2,
  UploadCloud, UserRound, UsersRound, WifiOff, X,
} from 'lucide-react'
import '../index.css'

const INITIAL_REQUESTS = [
  { id: 'VAC-2026-0148', employee: 'José Ramírez', initials: 'JR', area: 'Operaciones', type: 'Vacaciones', from: '2026-10-12', to: '2026-10-16', days: 5, status: 'Pendiente', approver: 'María Fernández', created: '09 oct 2026', updated: 'Hoy, 08:24', reason: 'Descanso anual programado.', backup: 'Carlos Ruiz', contact: '+51 999 245 183', documents: [], conflict: true, comments: 2, timeline: [['09 oct · 08:14', 'Solicitud creada'], ['09 oct · 08:23', 'Solicitud enviada'], ['09 oct · 08:24', 'Supervisor notificado']] },
  { id: 'PER-2026-0094', employee: 'Ana Torres', initials: 'AT', area: 'Comercial', type: 'Permiso personal', from: '2026-09-18', to: '2026-09-18', days: 1, status: 'Aprobada', approver: 'María Fernández', created: '15 set 2026', updated: '15 set, 16:32', reason: 'Trámite personal impostergable.', backup: 'Lucía Rey', contact: 'ana.torres@andina.pe', documents: [], conflict: false, comments: 1, timeline: [['15 set · 09:10', 'Solicitud creada'], ['15 set · 09:22', 'Solicitud enviada'], ['15 set · 16:32', 'María Fernández aprobó la solicitud']] },
  { id: 'MED-2026-0032', employee: 'Diego Salas', initials: 'DS', area: 'Almacén', type: 'Licencia médica', from: '2026-09-08', to: '2026-09-11', days: 4, status: 'Corrección requerida', approver: 'Rosa Chávez', created: '07 set 2026', updated: 'Ayer, 11:04', reason: 'Descanso médico por indicación profesional.', backup: 'Andrea Flores', contact: '', documents: ['certificado-medico.pdf'], conflict: false, comments: 3, timeline: [['07 set · 18:02', 'Solicitud enviada'], ['08 set · 09:10', 'Rosa Chávez solicitó corrección'], ['08 set · 09:11', 'Se solicitó adjuntar certificado legible']] },
  { id: 'VAC-2026-0137', employee: 'María Fernanda de los Ángeles del Rosario Valdivia Montoya', initials: 'MV', area: 'Finanzas', type: 'Vacaciones', from: '2026-11-03', to: '2026-11-07', days: 5, status: 'Borrador', approver: 'Alberto López', created: '06 set 2026', updated: 'Ayer, 17:20', reason: '', backup: '', contact: '', documents: [], conflict: false, comments: 0, timeline: [['06 set · 17:20', 'Borrador actualizado']] },
  { id: 'AUS-2026-0019', employee: 'Rafael Mendoza', initials: 'RM', area: 'Transporte', type: 'Ausencia justificada', from: '2026-09-03', to: '2026-09-03', days: 1, status: 'Rechazada', approver: 'Carlos Prado', created: '02 set 2026', updated: '03 set, 10:12', reason: 'Inasistencia justificada.', backup: '', contact: '', documents: ['sustento.pdf'], conflict: false, comments: 1, timeline: [['02 set · 17:40', 'Solicitud enviada'], ['03 set · 10:12', 'Carlos Prado rechazó la solicitud']] },
  { id: 'VAC-2026-0129', employee: 'Lucía Rey', initials: 'LR', area: 'Comercial', type: 'Vacaciones', from: '2026-08-19', to: '2026-08-22', days: 4, status: 'Cancelada', approver: 'María Fernández', created: '10 ago 2026', updated: '16 ago, 09:00', reason: 'Descanso anual.', backup: 'Ana Torres', contact: '', documents: [], conflict: false, comments: 1, timeline: [['10 ago · 10:00', 'Solicitud enviada'], ['11 ago · 15:12', 'Solicitud aprobada'], ['16 ago · 09:00', 'José Ramírez canceló la solicitud']] },
]

const ABSENCE_TYPES = [
  { id: 'vac', name: 'Vacaciones', code: 'VAC', balance: 'Sí', approval: 'Sí', document: 'No', state: 'Activo', modified: '09 set 2026' },
  { id: 'med', name: 'Licencia médica', code: 'MED', balance: 'No', approval: 'Sí', document: 'Sí', state: 'Activo', modified: '01 set 2026' },
  { id: 'per', name: 'Permiso personal', code: 'PER', balance: 'Configurable', approval: 'Sí', document: 'No', state: 'Activo', modified: '28 ago 2026' },
]

const EMPTY_FORM = { type: '', from: '', to: '', shift: 'Día completo', reason: '', paid: 'Con goce', backup: '', contact: '', comments: '', diagnosis: '', entity: '', certificate: '', attachment: '' }
const DEFAULT_FILTERS = { employee: 'Todos', area: 'Todas las áreas', type: 'Todos', status: 'Todos', date: 'Este periodo', supervisor: 'Todos' }
const FORM_STEPS = [{ id: 1, label: 'Periodo', hint: 'Tipo y fechas' }, { id: 2, label: 'Detalle', hint: 'Información adicional' }, { id: 3, label: 'Revisar', hint: 'Confirmación' }]

function App() {
  const [role, setRole] = useState('Empleado')
  const [view, setView] = useState('requests')
  const [requests, setRequests] = useState(INITIAL_REQUESTS)
  const [query, setQuery] = useState('')
  const [filters, setFilters] = useState(DEFAULT_FILTERS)
  const [filtersOpen, setFiltersOpen] = useState(false)
  const [selectedIds, setSelectedIds] = useState([])
  const [menuId, setMenuId] = useState(null)
  const [detail, setDetail] = useState(null)
  const [modal, setModal] = useState(null)
  const [form, setForm] = useState(EMPTY_FORM)
  const [formStep, setFormStep] = useState(1)
  const [formErrors, setFormErrors] = useState({})
  const [dirty, setDirty] = useState(false)
  const [saving, setSaving] = useState(false)
  const [loading, setLoading] = useState(false)
  const [notice, setNotice] = useState('')
  const [notifications, setNotifications] = useState([
    { id: 1, type: 'warning', text: 'Tienes 4 días de vacaciones que vencen el 31 de diciembre.', action: 'Revisar saldo', read: false },
    { id: 2, type: 'success', text: 'Tu solicitud VAC-2026-0098 fue aprobada.', action: 'Ver solicitud', read: false },
    { id: 3, type: 'info', text: 'Tu supervisor solicitó corregir una solicitud.', action: 'Continuar', read: true },
  ])

  const visibleRequests = useMemo(() => requests.filter((request) => {
    const term = query.trim().toLocaleLowerCase()
    const matchesSearch = !term || `${request.id} ${request.employee} ${request.type} ${request.area}`.toLocaleLowerCase().includes(term)
    const matchesStatus = filters.status === 'Todos' || request.status === filters.status
    const matchesType = filters.type === 'Todos' || request.type === filters.type
    const matchesArea = filters.area === 'Todas las áreas' || request.area === filters.area
    const matchesEmployee = role !== 'Empleado' || request.employee === 'José Ramírez'
    return matchesSearch && matchesStatus && matchesType && matchesArea && matchesEmployee
  }), [requests, filters, query, role])

  const activeFilters = Object.entries(filters).filter(([key, value]) => value !== DEFAULT_FILTERS[key]).map(([key, value]) => ({ key, label: `${filterLabel(key)}: ${value}` }))
  const todayBalance = 18
  const updateFilter = (key, value) => setFilters((current) => ({ ...current, [key]: value }))
  const flash = (message) => { setNotice(message); window.setTimeout(() => setNotice(''), 3400) }
  const refresh = () => { setLoading(true); window.setTimeout(() => { setLoading(false); flash('Solicitudes actualizadas') }, 950) }
  const updateForm = (key, value) => { setForm((current) => ({ ...current, [key]: value })); setDirty(true) }
  const createRequest = () => { setForm(EMPTY_FORM); setFormStep(1); setFormErrors({}); setDirty(false); setDetail(null); setView('form') }
  const editRequest = (request) => { setForm({ type: request.type, from: request.from, to: request.to, shift: 'Día completo', reason: request.reason, paid: 'Con goce', backup: request.backup, contact: request.contact, comments: '', diagnosis: '', entity: '', certificate: '', attachment: request.documents[0] || '' }); setFormStep(1); setFormErrors({}); setDirty(false); setDetail(null); setView('form') }
  const requestExit = () => dirty ? setModal({ kind: 'discard' }) : setView('requests')
  const saveDraft = () => persistForm('Borrador', true)
  const sendRequest = () => persistForm('Pendiente')
  const persistForm = (status, allowIncomplete = false) => {
    const errors = allowIncomplete ? {} : validateForm(form, formStep === 3)
    if (Object.keys(errors).length) { setFormErrors(errors); setFormStep(errors.from || errors.to || errors.type ? 1 : 2); return }
    setSaving(true)
    window.setTimeout(() => {
      const days = calculateDays(form.from, form.to)
      const newRequest = { id: `${form.type === 'Vacaciones' ? 'VAC' : form.type === 'Licencia médica' ? 'MED' : 'PER'}-2026-0161`, employee: 'José Ramírez', initials: 'JR', area: 'Operaciones', type: form.type, from: form.from, to: form.to, days, status, approver: 'María Fernández', created: 'Hoy', updated: 'Ahora', reason: form.reason || 'Sin detalle adicional.', backup: form.backup || 'Sin asignar', contact: form.contact, documents: form.attachment ? [form.attachment] : [], conflict: form.type === 'Vacaciones' && days >= 4, comments: 0, timeline: [['Ahora', status === 'Borrador' ? 'Borrador guardado' : 'Solicitud enviada'], ['Ahora', status === 'Borrador' ? 'Pendiente de completar' : 'María Fernández será notificada']] }
      setRequests((current) => [newRequest, ...current])
      setSaving(false); setDirty(false); setView('requests'); flash(status === 'Borrador' ? 'Borrador guardado correctamente' : 'Solicitud enviada correctamente. María Fernández recibirá la solicitud.')
    }, 800)
  }
  const updateRequestStatus = (request, status, message) => { setRequests((current) => current.map((item) => item.id === request.id ? { ...item, status, updated: 'Ahora', timeline: [...item.timeline, ['Ahora', message]] } : item)); setDetail(null); setModal(null); flash(message) }
  const toggleSelection = (id) => setSelectedIds((current) => current.includes(id) ? current.filter((item) => item !== id) : [...current, id])

  return <div className={`h-screen w-full overflow-x-hidden bg-[#f5f7fb] text-slate-900 ${detail || modal ? 'overflow-hidden' : 'overflow-y-auto overscroll-contain'}`}><ModuleHeader role={role} setRole={setRole} refresh={refresh} loading={loading} onCreate={createRequest} onAdmin={() => setView('types')} /><main className="mx-auto max-w-7xl px-5 py-7 sm:px-7 lg:px-10 lg:py-9">{view === 'form' ? <RequestForm form={form} update={updateForm} step={formStep} setStep={setFormStep} errors={formErrors} setErrors={setFormErrors} balance={todayBalance} saving={saving} onBack={requestExit} onDraft={saveDraft} onSend={sendRequest} /> : <><DashboardHeader view={view} setView={setView} role={role} /><PersonalSummary role={role} balance={todayBalance} onAdjust={() => setModal({ kind: 'adjust' })} /><Notifications items={notifications} setItems={setNotifications} onAction={() => setDetail(requests[0])} /><Subnav view={view} setView={setView} role={role} />{view === 'requests' && <RequestsWorkspace requests={visibleRequests} allRequests={requests} role={role} query={query} setQuery={setQuery} filters={filters} updateFilter={updateFilter} filtersOpen={filtersOpen} setFiltersOpen={setFiltersOpen} activeFilters={activeFilters} clearFilters={() => { setFilters(DEFAULT_FILTERS); setQuery('') }} selectedIds={selectedIds} setSelectedIds={setSelectedIds} toggleSelection={toggleSelection} menuId={menuId} setMenuId={setMenuId} onDetail={setDetail} onEdit={editRequest} onModal={setModal} onCreate={createRequest} loading={loading} />}{view === 'calendar' && <TeamCalendar requests={requests} onDetail={setDetail} />}{view === 'types' && <AbsenceTypes role={role} onModal={setModal} />}</>}</main>{detail && <RequestDrawer request={detail} role={role} onClose={() => setDetail(null)} onEdit={() => editRequest(detail)} onModal={setModal} />}{modal && <ActionModal modal={modal} onClose={() => setModal(null)} onAction={updateRequestStatus} onDiscard={() => { setModal(null); setDirty(false); setView('requests') }} flash={flash} />}{notice && <Toast>{notice}</Toast>}</div>
}

function ModuleHeader({ role, setRole, refresh, loading, onCreate, onAdmin }) { return <header className="sticky top-0 z-30 border-b border-slate-800 bg-slate-950 text-white"><div className="mx-auto flex h-[70px] max-w-7xl items-center justify-between px-5 sm:px-7 lg:px-10"><div className="flex items-center gap-3"><span className="flex h-9 w-9 items-center justify-center rounded-xl bg-indigo-500 text-sm font-bold shadow-lg shadow-indigo-950/70">A</span><div><p className="text-sm font-semibold">Andina People</p><p className="text-[11px] text-slate-400">Recursos Humanos</p></div></div><div className="flex items-center gap-2"><button type="button" onClick={refresh} className="hidden items-center gap-2 rounded-lg px-3 py-2 text-xs font-medium text-slate-300 transition hover:bg-white/10 sm:flex">{loading ? <Clock3 size={15} className="animate-spin text-indigo-300" /> : <CheckCircle2 size={15} className="text-emerald-400" />}{loading ? 'Actualizando' : 'Actualizado ahora'}</button><label className="relative hidden sm:block"><span className="sr-only">Vista de demostración por rol</span><select value={role} onChange={(event) => setRole(event.target.value)} className="h-9 appearance-none rounded-lg bg-white/10 pl-3 pr-8 text-xs font-semibold text-slate-200 outline-none hover:bg-white/15"><option className="text-slate-900">Empleado</option><option className="text-slate-900">Supervisor</option><option className="text-slate-900">RR. HH.</option><option className="text-slate-900">Administrador</option></select><ChevronDown size={14} className="pointer-events-none absolute right-2 top-2.5 text-slate-400" /></label>{(role === 'Empleado' || role === 'RR. HH.') && <button type="button" onClick={onCreate} className="inline-flex items-center gap-2 rounded-xl bg-indigo-500 px-3.5 py-2.5 text-sm font-semibold text-white shadow-lg shadow-indigo-950/60 hover:bg-indigo-400"><Plus size={16} />{role === 'RR. HH.' ? 'Registrar ausencia' : 'Nueva solicitud'}</button>}{(role === 'RR. HH.' || role === 'Administrador') && <button type="button" onClick={onAdmin} aria-label="Configuración de ausencias" className="rounded-lg p-2.5 text-slate-300 hover:bg-white/10"><Settings2 size={18} /></button>}</div></div></header> }

function DashboardHeader({ view, setView, role }) { return <div className="flex flex-wrap items-end justify-between gap-4"><div><div className="flex items-center gap-2 text-xs font-semibold text-indigo-600"><CalendarDays size={15} />GESTIÓN DE PERSONAS</div><h1 className="mt-3 text-3xl font-semibold tracking-[-.04em] text-slate-950 sm:text-4xl">Vacaciones y Ausencias</h1><p className="mt-2 text-sm text-slate-500">{role === 'Empleado' ? 'Consulta tu saldo, solicitudes y próximos descansos.' : role === 'Supervisor' ? 'Revisa y resuelve las solicitudes de tu equipo.' : 'Administra solicitudes, saldos y excepciones de personal.'}</p></div><button type="button" onClick={() => setView(view === 'calendar' ? 'requests' : 'calendar')} className="inline-flex items-center gap-2 rounded-xl border border-slate-200 bg-white px-3.5 py-2.5 text-sm font-semibold text-slate-700 shadow-sm hover:bg-slate-50"><CalendarDays size={16} />{view === 'calendar' ? 'Ver solicitudes' : 'Calendario del equipo'}</button></div> }

function PersonalSummary({ role, balance, onAdjust }) { return <section className="mt-6 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="grid lg:grid-cols-[1.15fr_.85fr_.85fr]"> <div className="p-5 sm:p-6"><p className="text-xs font-semibold uppercase tracking-[.12em] text-indigo-600">Resumen del periodo</p><div className="mt-3 flex items-end gap-4"><div><p className="text-4xl font-semibold tracking-[-.06em] text-slate-950">{balance}<span className="ml-1 text-lg text-slate-400">días</span></p><p className="mt-1 text-sm text-slate-500">Vacaciones disponibles</p></div><div className="mb-1 h-10 w-px bg-slate-200" /><div><p className="text-lg font-semibold text-slate-800">7 usados</p><p className="mt-1 text-xs text-slate-400">en el periodo actual</p></div></div></div><SummaryMetric label="Pendiente de aprobación" value="3 días" hint="1 solicitud activa" tone="amber" /><SummaryMetric label="Próximo descanso" value="12–16 oct" hint="5 días programados" tone="indigo" /> </div><div className="flex flex-wrap items-center justify-between gap-3 border-t border-slate-100 px-5 py-3.5 sm:px-6"><p className="flex items-center gap-2 text-xs text-amber-700"><AlertTriangle size={15} />4 días vencen el 31 de diciembre.</p>{role === 'RR. HH.' && <button type="button" onClick={onAdjust} className="text-xs font-semibold text-indigo-600 hover:text-indigo-700">Ajustar saldo</button>}</div></section> }

function SummaryMetric({ label, value, hint, tone }) { const colors = { amber: 'border-l-amber-400', indigo: 'border-l-indigo-400' }; return <div className={`border-t border-slate-100 border-l-4 p-5 lg:border-l lg:border-t-0 ${colors[tone]}`}><p className="text-xs font-semibold text-slate-500">{label}</p><p className="mt-2 text-xl font-semibold tracking-[-.03em] text-slate-950">{value}</p><p className="mt-1 text-xs text-slate-400">{hint}</p></div> }

function Notifications({ items, setItems, onAction }) { return <section className="mt-5 flex gap-3 overflow-x-auto pb-1">{items.map((item) => <Notification key={item.id} item={item} onDismiss={() => setItems((current) => current.filter((notification) => notification.id !== item.id))} onAction={onAction} />)}</section> }

function Notification({ item, onDismiss, onAction }) { const styles = { warning: 'border-amber-100 bg-amber-50 text-amber-800', success: 'border-emerald-100 bg-emerald-50 text-emerald-800', info: 'border-indigo-100 bg-indigo-50 text-indigo-800' }; const icons = { warning: AlertTriangle, success: CheckCircle2, info: BellRing }; const Icon = icons[item.type]; return <article className={`flex min-w-[310px] flex-1 items-start gap-3 rounded-xl border px-3.5 py-3 ${styles[item.type]}`}><Icon size={17} className="mt-0.5 shrink-0" /><div className="min-w-0 flex-1"><p className="text-xs leading-5">{item.text}</p><button type="button" onClick={onAction} className="mt-1.5 text-xs font-bold underline underline-offset-2">{item.action}</button></div><button type="button" onClick={onDismiss} aria-label="Cerrar aviso" className="rounded p-1 opacity-60 hover:bg-white/50 hover:opacity-100"><X size={14} /></button></article> }

function Subnav({ view, setView, role }) { return <nav className="mt-7 flex gap-1 overflow-x-auto border-b border-slate-200"><Tab active={view === 'requests'} onClick={() => setView('requests')}>Solicitudes</Tab><Tab active={view === 'calendar'} onClick={() => setView('calendar')}>Calendario</Tab>{(role === 'RR. HH.' || role === 'Administrador') && <Tab active={view === 'types'} onClick={() => setView('types')}>Tipos de ausencia</Tab>}</nav> }
function Tab({ active, children, onClick }) { return <button type="button" onClick={onClick} className={`whitespace-nowrap border-b-2 px-3.5 py-3 text-sm font-semibold transition ${active ? 'border-indigo-600 text-indigo-700' : 'border-transparent text-slate-500 hover:text-slate-800'}`}>{children}</button> }

function RequestsWorkspace({ requests, allRequests, role, query, setQuery, filters, updateFilter, filtersOpen, setFiltersOpen, activeFilters, clearFilters, selectedIds, setSelectedIds, toggleSelection, menuId, setMenuId, onDetail, onEdit, onModal, onCreate, loading }) { const canBulk = role === 'RR. HH.' || role === 'Administrador'; return <section className="mt-5"><div className="rounded-2xl border border-slate-200 bg-white p-3 shadow-sm"><div className="flex flex-wrap items-center gap-3"><label className="flex h-11 min-w-[230px] flex-1 items-center gap-2 rounded-xl bg-slate-100 px-3.5 focus-within:bg-white focus-within:ring-2 focus-within:ring-indigo-100"><Search size={16} className="text-slate-400" /><input value={query} onChange={(event) => setQuery(event.target.value)} className="w-full bg-transparent text-sm outline-none placeholder:text-slate-400" placeholder="Buscar solicitud, empleado o área" /></label><button type="button" onClick={() => setFiltersOpen(!filtersOpen)} className={`inline-flex h-11 items-center gap-2 rounded-xl border px-3.5 text-sm font-semibold ${filtersOpen ? 'border-indigo-200 bg-indigo-50 text-indigo-700' : 'border-slate-200 text-slate-700 hover:bg-slate-50'}`}><SlidersHorizontal size={16} />Filtros{activeFilters.length ? <span className="rounded-md bg-indigo-100 px-1.5 py-0.5 text-[11px]">{activeFilters.length}</span> : null}</button>{(activeFilters.length > 0 || query) && <button type="button" onClick={clearFilters} className="px-2 text-xs font-semibold text-slate-500 hover:text-slate-900">Limpiar</button>}</div>{activeFilters.length > 0 && <div className="flex flex-wrap gap-2 px-1 pt-3">{activeFilters.map((filter) => <span key={filter.key} className="inline-flex items-center gap-1.5 rounded-full bg-slate-100 px-2.5 py-1.5 text-xs text-slate-600">{filter.label}<button type="button" onClick={() => updateFilter(filter.key, DEFAULT_FILTERS[filter.key])} aria-label={`Quitar ${filter.label}`}><X size={13} /></button></span>)}</div>}{filtersOpen && <div className="mt-3 grid gap-3 border-t border-slate-100 pt-4 sm:grid-cols-2 lg:grid-cols-3"><SelectFilter label="Empleado" value={filters.employee} onChange={(value) => updateFilter('employee', value)}><option>Todos</option><option>José Ramírez</option><option>Ana Torres</option></SelectFilter><SelectFilter label="Área" value={filters.area} onChange={(value) => updateFilter('area', value)}><option>Todas las áreas</option><option>Operaciones</option><option>Comercial</option><option>Almacén</option></SelectFilter><SelectFilter label="Tipo" value={filters.type} onChange={(value) => updateFilter('type', value)}><option>Todos</option><option>Vacaciones</option><option>Permiso personal</option><option>Licencia médica</option></SelectFilter><SelectFilter label="Estado" value={filters.status} onChange={(value) => updateFilter('status', value)}><option>Todos</option><option>Borrador</option><option>Pendiente</option><option>Corrección requerida</option><option>Aprobada</option><option>Rechazada</option><option>Cancelada</option></SelectFilter><SelectFilter label="Rango de fechas" value={filters.date} onChange={(value) => updateFilter('date', value)}><option>Este periodo</option><option>Últimos 30 días</option><option>Personalizado</option></SelectFilter><SelectFilter label="Supervisor" value={filters.supervisor} onChange={(value) => updateFilter('supervisor', value)}><option>Todos</option><option>María Fernández</option><option>Rosa Chávez</option></SelectFilter></div>}</div><section className="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 px-5 py-5 sm:px-6"><div><div className="flex items-center gap-2 text-xs font-semibold text-indigo-600"><FileText size={16} />SOLICITUDES</div><h2 className="mt-2 text-xl font-semibold tracking-[-.03em] text-slate-950">{role === 'Empleado' ? 'Mis solicitudes' : role === 'Supervisor' ? 'Solicitudes de mi equipo' : 'Todas las solicitudes'}</h2></div>{canBulk && selectedIds.length > 0 ? <div className="flex items-center gap-2 rounded-xl bg-indigo-50 p-1.5 text-xs"><span className="px-2 font-semibold text-indigo-700">{selectedIds.length} seleccionadas</span><button type="button" className="rounded-lg bg-white px-2.5 py-2 font-semibold text-slate-700 shadow-sm">Exportar</button><button type="button" onClick={() => setSelectedIds([])} className="rounded-lg px-2 py-2 text-slate-500">Limpiar</button></div> : <button type="button" onClick={onCreate} className="text-xs font-semibold text-indigo-600 hover:text-indigo-700">Crear solicitud</button>}</div>{loading ? <TableSkeleton /> : <RequestsTable rows={requests} allRows={allRequests} role={role} selectedIds={selectedIds} setSelectedIds={setSelectedIds} toggleSelection={toggleSelection} menuId={menuId} setMenuId={setMenuId} onDetail={onDetail} onEdit={onEdit} onModal={onModal} clearFilters={clearFilters} />}</section></section> }

function SelectFilter({ label, value, onChange, children }) { return <label><span className="mb-1.5 block text-[11px] font-semibold text-slate-500">{label}</span><div className="relative"><select value={value} onChange={(event) => onChange(event.target.value)} className="h-10 w-full appearance-none rounded-xl border border-slate-200 bg-white px-3 text-sm text-slate-700 outline-none focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100">{children}</select><ChevronDown size={15} className="pointer-events-none absolute right-3 top-3 text-slate-400" /></div></label> }

function RequestsTable({ rows, allRows, role, selectedIds, setSelectedIds, toggleSelection, menuId, setMenuId, onDetail, onEdit, onModal, clearFilters }) { const canBulk = role === 'RR. HH.' || role === 'Administrador'; if (!rows.length) return <EmptyState onClear={clearFilters} />; const allSelected = rows.every((request) => selectedIds.includes(request.id)); const toggleAll = () => setSelectedIds(allSelected ? selectedIds.filter((id) => !rows.some((request) => request.id === id)) : [...new Set([...selectedIds, ...rows.map((request) => request.id)])]); return <div className="overflow-x-auto"><div className="min-w-[970px]"><div className="grid grid-cols-[34px_132px_minmax(170px,1.25fr)_115px_92px_90px_118px_130px_44px] gap-4 border-b border-slate-100 bg-slate-50/70 px-5 py-3 text-[10px] font-bold uppercase tracking-[.1em] text-slate-400 sm:px-6"><span>{canBulk ? <input type="checkbox" checked={allSelected} onChange={toggleAll} aria-label="Seleccionar todas" className="h-4 w-4 rounded border-slate-300 text-indigo-600" /> : null}</span><span>Solicitud</span><span>Empleado</span><span>Tipo</span><span>Periodo</span><span>Días</span><span>Estado</span><span>Aprobador</span><span /></div>{rows.map((request) => <RequestRow key={request.id} request={request} role={role} selected={selectedIds.includes(request.id)} onToggle={() => toggleSelection(request.id)} menuOpen={menuId === request.id} onMenu={(open) => setMenuId(open ? request.id : null)} onDetail={() => { setMenuId(null); onDetail(request) }} onEdit={() => onEdit(request)} onModal={onModal} />)}<div className="flex items-center justify-between border-t border-slate-100 px-5 py-3.5 text-xs text-slate-500 sm:px-6"><span>Mostrando {rows.length} de {allRows.length} solicitudes</span><div className="flex items-center gap-1"><button disabled className="rounded-lg p-1.5 text-slate-300"><ChevronLeft size={16} /></button><span className="rounded-lg bg-indigo-50 px-2.5 py-1.5 font-semibold text-indigo-700">1</span><button disabled className="rounded-lg p-1.5 text-slate-300"><ChevronRight size={16} /></button></div></div></div></div> }

function RequestRow({ request, role, selected, onToggle, menuOpen, onMenu, onDetail, onEdit, onModal }) { const editable = request.status === 'Borrador' || request.status === 'Corrección requerida'; const canApprove = role === 'Supervisor' && request.status === 'Pendiente'; return <div className={`group grid grid-cols-[34px_132px_minmax(170px,1.25fr)_115px_92px_90px_118px_130px_44px] items-center gap-4 border-b border-slate-100 px-5 py-4 last:border-0 hover:bg-slate-50/80 sm:px-6 ${selected ? 'bg-indigo-50/50' : ''}`}><span>{(role === 'RR. HH.' || role === 'Administrador') ? <input type="checkbox" checked={selected} onChange={onToggle} aria-label={`Seleccionar ${request.id}`} className="h-4 w-4 rounded border-slate-300 text-indigo-600" /> : null}</span><button type="button" onClick={onDetail} className="min-w-0 text-left"><span className="block truncate text-sm font-semibold text-slate-900 hover:text-indigo-700">{request.id}</span><span className="mt-1 block text-[11px] text-slate-400">{request.updated}</span></button><div className="min-w-0"><p className="truncate text-xs font-semibold text-slate-700">{request.employee}</p><p className="mt-1 truncate text-[11px] text-slate-400">{request.area}</p></div><span className="truncate text-xs text-slate-600">{request.type}</span><span className="text-xs text-slate-600">{formatRange(request.from, request.to)}</span><span className="text-xs font-semibold text-slate-700">{request.days}</span><WorkflowBadge value={request.status} /><span className="truncate text-xs text-slate-600">{request.approver}</span><div className="relative"><button type="button" onClick={() => onMenu(!menuOpen)} aria-label={`Acciones de ${request.id}`} className="rounded-lg p-2 text-slate-400 hover:bg-white hover:text-slate-700 sm:opacity-0 sm:group-hover:opacity-100"><MoreHorizontal size={18} /></button>{menuOpen && <RequestMenu editable={editable} canApprove={canApprove} request={request} onDetail={onDetail} onEdit={onEdit} onModal={onModal} />}</div></div> }

function RequestMenu({ editable, canApprove, request, onDetail, onEdit, onModal }) { return <div className="absolute right-0 top-9 z-20 w-48 rounded-xl border border-slate-200 bg-white p-1.5 shadow-xl shadow-slate-900/10"><MenuButton icon={Search} onClick={onDetail}>Ver detalle</MenuButton>{editable && <MenuButton icon={Pencil} onClick={onEdit}>Editar solicitud</MenuButton>}{canApprove && <><MenuButton icon={Check} onClick={() => onModal({ kind: request.conflict ? 'approve-conflict' : 'approve', request })}>Aprobar</MenuButton><MenuButton icon={CircleAlert} onClick={() => onModal({ kind: 'reject', request })}>Rechazar</MenuButton><MenuButton icon={Pencil} onClick={() => onModal({ kind: 'correction', request })}>Solicitar corrección</MenuButton></>}{['Pendiente', 'Aprobada', 'Borrador', 'Corrección requerida'].includes(request.status) && <><div className="my-1 border-t border-slate-100" /><MenuButton icon={Trash2} danger onClick={() => onModal({ kind: 'cancel', request })}>Cancelar solicitud</MenuButton></>}</div> }

function MenuButton({ icon, children, onClick, danger = false }) { const Icon = icon; return <button type="button" onClick={onClick} className={`flex w-full items-center gap-2 rounded-lg px-3 py-2 text-left text-xs font-medium ${danger ? 'text-rose-600 hover:bg-rose-50' : 'text-slate-700 hover:bg-slate-50'}`}><Icon size={14} />{children}</button> }

function RequestForm({ form, update, step, setStep, errors, setErrors, balance, saving, onBack, onDraft, onSend }) { const days = calculateDays(form.from, form.to); const goNext = () => { const errs = validateForm(form, false); setErrors(errs); if (Object.keys(errs).length) return; setStep(Math.min(3, step + 1)) }; return <><button type="button" onClick={onBack} className="mb-7 inline-flex items-center gap-2 text-sm font-semibold text-slate-500 hover:text-slate-900"><ArrowLeft size={16} />Volver a solicitudes</button><div className="mx-auto max-w-5xl"><div className="flex flex-wrap items-end justify-between gap-4 border-b border-slate-200 pb-7"><div><div className="flex items-center gap-2 text-xs font-semibold text-indigo-600"><FileText size={15} />NUEVA SOLICITUD</div><h1 className="mt-3 text-3xl font-semibold tracking-[-.04em] text-slate-950">Solicita una ausencia</h1><p className="mt-2 text-sm text-slate-500">Un proceso corto. Verás solo la información necesaria para tu tipo de solicitud.</p></div><p className="flex items-center gap-2 text-xs text-slate-400"><Clock3 size={14} />Guardado automático hace unos segundos</p></div><div className="mt-8 grid gap-7 lg:grid-cols-[210px_minmax(0,1fr)]"><FormSteps step={step} setStep={setStep} /><section className="rounded-2xl border border-slate-200 bg-white p-6 shadow-sm sm:p-8">{step === 1 && <PeriodStep form={form} update={update} errors={errors} days={days} balance={balance} />}{step === 2 && <DetailsStep form={form} update={update} errors={errors} />}{step === 3 && <ReviewStep form={form} days={days} balance={balance} />}<div className="mt-8 flex items-center justify-between border-t border-slate-100 pt-5"><button type="button" onClick={() => setStep(Math.max(1, step - 1))} className={`inline-flex items-center gap-2 rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-500 hover:bg-slate-50 ${step === 1 ? 'invisible' : ''}`}><ArrowLeft size={16} />Anterior</button>{step < 3 ? <button type="button" onClick={goNext} className="inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white shadow-lg shadow-indigo-100 hover:bg-indigo-700">Continuar<ArrowRight size={16} /></button> : <div className="flex gap-2"><button type="button" disabled={saving} onClick={onDraft} className="rounded-xl border border-slate-200 px-3.5 py-2.5 text-sm font-semibold text-slate-700 hover:bg-slate-50">Guardar borrador</button><button type="button" disabled={saving} onClick={onSend} className="inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-4 py-2.5 text-sm font-semibold text-white shadow-lg shadow-indigo-100 hover:bg-indigo-700 disabled:bg-slate-300">{saving ? <Clock3 size={16} className="animate-spin" /> : <Check size={16} />}{saving ? 'Enviando...' : 'Enviar solicitud'}</button></div>}</div></section></div></div></> }

function FormSteps({ step, setStep }) { return <ol className="flex gap-2 overflow-x-auto pb-1 lg:block lg:space-y-1">{FORM_STEPS.map((item) => <li key={item.id}><button type="button" disabled={item.id > step} onClick={() => setStep(item.id)} className={`flex min-w-[150px] items-center gap-3 rounded-xl p-3 text-left lg:w-full ${item.id === step ? 'bg-indigo-50' : 'disabled:cursor-default'}`}><span className={`flex h-7 w-7 items-center justify-center rounded-full text-[11px] font-bold ${item.id < step ? 'bg-emerald-500 text-white' : item.id === step ? 'bg-indigo-600 text-white' : 'bg-slate-200 text-slate-500'}`}>{item.id < step ? <Check size={14} /> : item.id}</span><span><span className={`block text-sm font-semibold ${item.id <= step ? 'text-slate-800' : 'text-slate-400'}`}>{item.label}</span><span className="mt-0.5 block text-[11px] text-slate-400">{item.hint}</span></span></button></li>)}</ol> }

function PeriodStep({ form, update, errors, days, balance }) { return <><FormHeader icon={CalendarDays} eyebrow="Paso 1 · Periodo" title="¿Cuándo necesitas ausentarte?" text="Selecciona el tipo y las fechas. Calcularemos el impacto antes de enviar." /><div className="grid gap-4 sm:grid-cols-2"><Field label="Tipo de ausencia" error={errors.type}><Select value={form.type} onChange={(event) => update('type', event.target.value)}><option value="">Selecciona una opción</option><option>Vacaciones</option><option>Permiso personal</option><option>Licencia médica</option><option>Licencia por maternidad/paternidad</option><option>Compensación</option><option>Otro</option></Select></Field><Field label="Jornada"><div className="grid grid-cols-3 rounded-xl bg-slate-100 p-1">{['Día completo', 'Medio día mañana', 'Medio día tarde'].map((value) => <button type="button" key={value} onClick={() => update('shift', value)} className={`rounded-lg px-2 py-2 text-[11px] font-semibold ${form.shift === value ? 'bg-white text-slate-900 shadow-sm' : 'text-slate-500'}`}>{value.replace('Medio día ', '')}</button>)}</div></Field><Field label="Fecha inicial" error={errors.from}><input type="date" value={form.from} onChange={(event) => update('from', event.target.value)} className={inputClass} /></Field><Field label="Fecha final" error={errors.to}><input type="date" value={form.to} onChange={(event) => update('to', event.target.value)} className={inputClass} /></Field></div>{form.from && form.to && <div className="mt-5 grid gap-3 sm:grid-cols-3"><MiniStat label="Días calendario" value={days} /><MiniStat label="Días laborables" value={days} /><MiniStat label="Feriados" value="0" /></div>}{form.type === 'Vacaciones' && <VacationContext balance={balance} days={days} />}{form.type === 'Permiso personal' && <div className="mt-6"><Field label="Condición del permiso"><div className="grid grid-cols-2 gap-3"><Choice active={form.paid === 'Con goce'} onClick={() => update('paid', 'Con goce')} title="Con goce" text="Mantiene la remuneración." /><Choice active={form.paid === 'Sin goce'} onClick={() => update('paid', 'Sin goce')} title="Sin goce" text="Se descuenta según la política." /></div></Field></div>}{form.type === 'Licencia médica' && <MedicalFields form={form} update={update} errors={errors} />}</> }

function VacationContext({ balance, days }) { const remaining = balance - days; return <div className="mt-6 rounded-2xl border border-indigo-100 bg-indigo-50 p-4"><div className="flex flex-wrap items-start justify-between gap-4"><div><p className="text-sm font-semibold text-indigo-950">Saldo de vacaciones</p><p className="mt-1 text-xs text-indigo-700">Disponible: {balance} días · Después de esta solicitud: {remaining} días</p></div><span className={`rounded-full px-2.5 py-1 text-xs font-semibold ${remaining < 0 ? 'bg-rose-100 text-rose-700' : 'bg-white text-indigo-700'}`}>{remaining < 0 ? 'Saldo insuficiente' : 'Saldo disponible'}</span></div><div className="mt-4 border-t border-indigo-100 pt-4"><p className="text-xs font-bold uppercase tracking-[.1em] text-indigo-700">Disponibilidad del equipo</p><div className="mt-2 grid grid-cols-3 gap-2 text-center">{[['12 oct', '2 ausentes'], ['13 oct', '3 ausentes'], ['14 oct', '3 ausentes']].map(([day, value]) => <div key={day} className="rounded-xl bg-white px-2 py-2.5"><p className="text-xs font-semibold text-slate-700">{day}</p><p className="mt-1 text-[11px] text-amber-700">{value}</p></div>)}</div><p className="mt-3 flex items-center gap-1.5 text-xs text-amber-700"><AlertTriangle size={14} />Existe un conflicto potencial con fechas críticas del equipo.</p></div></div> }

function MedicalFields({ form, update, errors }) { return <div className="mt-6 rounded-2xl border border-rose-100 bg-rose-50/50 p-4"><p className="text-sm font-semibold text-slate-900">Información de licencia médica</p><p className="mt-1 text-xs text-slate-500">El certificado es obligatorio para completar la solicitud.</p><div className="mt-4 grid gap-4 sm:grid-cols-2"><Field label="Motivo administrativo" error={errors.diagnosis}><input value={form.diagnosis} onChange={(event) => update('diagnosis', event.target.value)} className={inputClass} placeholder="Ej. Descanso médico" /></Field><Field label="Entidad médica" error={errors.entity}><input value={form.entity} onChange={(event) => update('entity', event.target.value)} className={inputClass} placeholder="Ej. Clínica Andina" /></Field><Field label="Número de certificado" error={errors.certificate}><input value={form.certificate} onChange={(event) => update('certificate', event.target.value)} className={inputClass} placeholder="Ej. CM-004198" /></Field><Field label="Certificado médico" error={errors.attachment}><button type="button" onClick={() => update('attachment', 'certificado-medico.pdf')} className="flex h-11 w-full items-center justify-center gap-2 rounded-xl border border-dashed border-slate-300 bg-white text-sm font-semibold text-slate-600 hover:border-indigo-400 hover:text-indigo-700"><UploadCloud size={16} />{form.attachment || 'Adjuntar archivo'}</button></Field></div></div> }

function DetailsStep({ form, update, errors }) { const reasonRequired = ['Permiso personal', 'Otro'].includes(form.type); return <><FormHeader icon={UserRound} eyebrow="Paso 2 · Detalle" title="Completa la información necesaria" text="Estos datos ayudan a tu equipo a mantener la continuidad durante tu ausencia." /><div className="grid gap-4 sm:grid-cols-2"><Field label="Persona de respaldo"><Select value={form.backup} onChange={(event) => update('backup', event.target.value)}><option value="">Selecciona una persona</option><option>Carlos Ruiz</option><option>Andrea Flores</option><option>Lucía Rey</option></Select></Field><Field label="Contacto durante la ausencia"><input value={form.contact} onChange={(event) => update('contact', event.target.value)} className={inputClass} placeholder="Correo o teléfono (opcional)" /></Field></div><div className="mt-5"><Field label={`Motivo ${reasonRequired ? '' : '(opcional)'}`} error={errors.reason}><textarea value={form.reason} onChange={(event) => update('reason', event.target.value)} className={`${inputClass} h-24 resize-none py-3`} placeholder="Incluye solo la información necesaria para gestionar la solicitud." /></Field></div><div className="mt-5"><Field label="Comentarios adicionales"><textarea value={form.comments} onChange={(event) => update('comments', event.target.value)} className={`${inputClass} h-20 resize-none py-3`} placeholder="Información adicional para tu supervisor (opcional)." /></Field></div>{form.type !== 'Licencia médica' && <div className="mt-6"><p className="text-xs font-semibold text-slate-700">Adjuntos</p><button type="button" onClick={() => update('attachment', 'sustento.pdf')} className="mt-1.5 flex min-h-24 w-full flex-col items-center justify-center rounded-xl border border-dashed border-slate-300 bg-slate-50 text-xs text-slate-500 hover:border-indigo-400"><UploadCloud size={18} className="mb-2 text-slate-400" />{form.attachment || 'Adjunta un sustento si corresponde'}</button><p className="mt-2 text-[11px] text-slate-400">PDF, JPG o PNG hasta 10 MB.</p></div>}</> }

function ReviewStep({ form, days, balance }) { return <><FormHeader icon={BadgeCheck} eyebrow="Paso 3 · Revisar" title="Todo listo para enviar" text="Revisa el resumen. Podrás cancelar la solicitud cuando la política lo permita." /><div className="overflow-hidden rounded-2xl border border-slate-200"><ReviewRow label="Solicitud" value={form.type || 'Sin tipo'} detail={form.shift} /><ReviewRow label="Periodo" value={formatRange(form.from, form.to)} detail={`${days} días laborables`} /><ReviewRow label="Saldo actual" value={`${balance} días`} detail={`Después de la solicitud: ${balance - days} días`} /><ReviewRow label="Aprobador" value="María Fernández" detail={`Respaldo: ${form.backup || 'Sin asignar'}`} /></div>{form.type === 'Vacaciones' && days >= 4 && <div className="mt-4 flex gap-3 rounded-xl border border-amber-100 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><AlertTriangle size={18} className="mt-1 shrink-0 text-amber-600" /><p>Durante esas fechas ya existen 3 personas del equipo ausentes. Tu supervisor podrá aprobar de todas formas.</p></div>}</> }

function FormHeader({ icon, eyebrow, title, text }) { const Icon = icon; return <div className="mb-7"><div className="flex items-center gap-2 text-xs font-semibold text-indigo-600"><Icon size={15} />{eyebrow}</div><h2 className="mt-3 text-xl font-semibold tracking-[-.025em] text-slate-950">{title}</h2><p className="mt-1.5 max-w-xl text-sm leading-6 text-slate-500">{text}</p></div> }
function Field({ label, children, error }) { return <label className="block"><span className="text-xs font-semibold text-slate-700">{label}</span><div className={`mt-1.5 ${error ? '[&>input]:border-rose-400 [&>textarea]:border-rose-400 [&>input]:focus:ring-rose-100 [&>textarea]:focus:ring-rose-100' : ''}`}>{children}</div>{error && <span className="mt-1.5 block text-[11px] font-medium text-rose-600">{error}</span>}</label> }
function Select({ children, ...props }) { return <div className="relative"><select {...props} className={`${inputClass} appearance-none pr-10`}>{children}</select><ChevronDown size={16} className="pointer-events-none absolute right-3 top-3 text-slate-400" /></div> }
function Choice({ active, onClick, title, text }) { return <button type="button" onClick={onClick} className={`rounded-xl border p-3 text-left ${active ? 'border-indigo-500 bg-indigo-50 ring-1 ring-indigo-500' : 'border-slate-200 bg-white hover:bg-slate-50'}`}><p className="text-sm font-semibold text-slate-800">{title}</p><p className="mt-1 text-xs text-slate-500">{text}</p></button> }
function MiniStat({ label, value }) { return <div className="rounded-xl bg-slate-50 px-3.5 py-3"><p className="text-[11px] font-semibold text-slate-500">{label}</p><p className="mt-1 text-lg font-semibold text-slate-800">{value}</p></div> }
function ReviewRow({ label, value, detail }) { return <div className="flex items-center justify-between gap-5 border-b border-slate-100 p-4 last:border-0"><div><p className="text-[11px] font-bold uppercase tracking-[.1em] text-slate-400">{label}</p><p className="mt-1 text-xs text-slate-500">{detail}</p></div><p className="max-w-[52%] text-right text-sm font-semibold text-slate-900">{value}</p></div> }

function RequestDrawer({ request, role, onClose, onEdit, onModal }) { const canEdit = (request.status === 'Borrador' || request.status === 'Corrección requerida') && role === 'Empleado'; const canReview = role === 'Supervisor' && request.status === 'Pendiente'; return <><div className="fixed inset-0 z-40 bg-slate-950/35" role="presentation" /><aside role="dialog" aria-modal="true" aria-labelledby="drawer-title" className="fixed bottom-3 top-3 z-50 flex w-[min(450px,calc(100vw-1.5rem))] flex-col overflow-hidden rounded-2xl bg-white shadow-2xl shadow-slate-950/30" style={{ right: 'max(0.75rem, calc((100vw - 80rem) / 2))' }}><div className="border-b border-slate-100 px-5 py-5"><div className="flex items-start justify-between gap-4"><div><p className="text-xs font-semibold text-indigo-600">SOLICITUD DE AUSENCIA</p><h2 id="drawer-title" className="mt-1 text-lg font-semibold text-slate-950">{request.id}</h2></div><button type="button" onClick={onClose} aria-label="Cerrar detalle" className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><X size={18} /></button></div><div className="mt-4 flex flex-wrap items-center gap-2"><WorkflowBadge value={request.status} /><span className="text-xs text-slate-500">{request.type}</span></div></div><div className="flex-1 overflow-y-auto px-5 py-5"><DrawerHeading icon={UserRound} title="Solicitante" /><div className="flex items-center gap-3"><Avatar initials={request.initials} /><div className="min-w-0"><p className="truncate text-sm font-semibold text-slate-900">{request.employee}</p><p className="mt-1 text-xs text-slate-500">{request.area}</p></div></div><DrawerSection title="Periodo"><div className="grid grid-cols-3 divide-x divide-slate-100 overflow-hidden rounded-xl border border-slate-100"><DetailMetric label="Desde" value={formatDate(request.from)} /><DetailMetric label="Hasta" value={formatDate(request.to)} /><DetailMetric label="Laborables" value={`${request.days} días`} /></div></DrawerSection>{request.type === 'Vacaciones' && <DrawerSection title="Saldo"><div className="grid grid-cols-3 divide-x divide-slate-100 overflow-hidden rounded-xl border border-slate-100"><DetailMetric label="Antes" value="18 días" /><DetailMetric label="Solicitado" value={`${request.days} días`} /><DetailMetric label="Después" value={`${18 - request.days} días`} /></div></DrawerSection>}<DrawerSection title="Motivo"><p className="rounded-xl bg-slate-50 p-3.5 text-sm leading-6 text-slate-600">{request.reason || 'No se registró un motivo adicional.'}</p></DrawerSection><DrawerSection title="Aprobación"><InfoRow label="Supervisor" value={request.approver} /><InfoRow label="Estado" value={request.status} /><InfoRow label="Persona de respaldo" value={request.backup || 'Sin asignar'} /></DrawerSection><DrawerSection title="Historial de actividad"><ol className="space-y-3">{request.timeline.map(([time, text], index) => <li key={`${time}-${text}`} className="flex gap-3"><span className={`mt-1.5 h-2.5 w-2.5 shrink-0 rounded-full ${index === request.timeline.length - 1 ? 'bg-indigo-500 ring-4 ring-indigo-100' : 'bg-slate-300'}`} /><div><p className="text-xs font-semibold text-slate-500">{time}</p><p className="mt-0.5 text-sm text-slate-700">{text}</p></div></li>)}</ol></DrawerSection><DrawerSection title="Documentos"><div className="space-y-2">{request.documents.length ? request.documents.map((document) => <button key={document} type="button" className="flex w-full items-center gap-2 rounded-xl border border-slate-200 px-3 py-2.5 text-left text-xs font-semibold text-slate-700 hover:bg-slate-50"><FileText size={15} className="text-indigo-600" /><span className="min-w-0 flex-1 truncate">{document}</span><Download size={14} className="text-slate-400" /></button>) : <p className="rounded-xl bg-slate-50 p-3 text-xs text-slate-500">No hay adjuntos para esta solicitud.</p>}</div></DrawerSection><DrawerSection title={`Comentarios · ${request.comments}`}><div className="rounded-xl bg-slate-50 p-3 text-xs text-slate-500">Los comentarios y menciones se integrarán al conectar el backend de colaboración.</div></DrawerSection></div><div className="border-t border-slate-100 p-4">{canReview ? <div className="grid grid-cols-3 gap-2"><DrawerAction icon={Check} onClick={() => onModal({ kind: request.conflict ? 'approve-conflict' : 'approve', request })}>Aprobar</DrawerAction><DrawerAction icon={CircleAlert} onClick={() => onModal({ kind: 'reject', request })}>Rechazar</DrawerAction><DrawerAction icon={Pencil} onClick={() => onModal({ kind: 'correction', request })}>Corregir</DrawerAction></div> : <div className="grid grid-cols-2 gap-2">{canEdit && <DrawerAction icon={Pencil} onClick={onEdit}>Editar</DrawerAction>}{['Pendiente', 'Aprobada', 'Borrador', 'Corrección requerida'].includes(request.status) && <DrawerAction icon={Trash2} danger onClick={() => onModal({ kind: 'cancel', request })}>Cancelar</DrawerAction>}<DrawerAction icon={Search} onClick={() => onModal({ kind: 'full-detail', request })}>Ver completo</DrawerAction></div>}</div></aside></> }

function DrawerHeading({ icon, title }) { const Icon = icon; return <h3 className="mb-3 flex items-center gap-2 text-[11px] font-bold uppercase tracking-[.11em] text-slate-400"><Icon size={14} />{title}</h3> }
function DrawerSection({ title, children }) { return <section className="mb-6"><h3 className="mb-3 text-[11px] font-bold uppercase tracking-[.11em] text-slate-400">{title}</h3>{children}</section> }
function DetailMetric({ label, value }) { return <div className="p-3 text-center"><p className="text-[10px] font-semibold text-slate-400">{label}</p><p className="mt-1 text-xs font-semibold text-slate-800">{value}</p></div> }
function InfoRow({ label, value }) { return <div className="flex items-center justify-between gap-4 border-b border-slate-100 py-2.5 first:pt-0 last:border-0"><span className="text-xs text-slate-500">{label}</span><span className="max-w-[60%] text-right text-xs font-semibold text-slate-800">{value}</span></div> }
function DrawerAction({ icon, children, onClick, danger = false }) { const Icon = icon; return <button type="button" onClick={onClick} className={`flex items-center justify-center gap-1.5 rounded-xl border px-2 py-2.5 text-xs font-semibold ${danger ? 'border-rose-200 text-rose-600 hover:bg-rose-50' : 'border-slate-200 text-slate-700 hover:border-indigo-200 hover:bg-indigo-50 hover:text-indigo-700'}`}><Icon size={14} />{children}</button> }

function ActionModal({ modal, onClose, onAction, onDiscard, flash }) { const [reason, setReason] = useState(''); const [amount, setAmount] = useState('2'); const request = modal.request; const requiresReason = ['cancel', 'reject', 'correction'].includes(modal.kind); const titles = { cancel: 'Cancelar solicitud', reject: 'Rechazar solicitud', correction: 'Solicitar corrección', 'approve-conflict': 'Aprobar con advertencia', approve: 'Aprobar solicitud', adjust: 'Ajustar saldo', discard: 'Tienes cambios sin guardar', 'type-config': modal.editing ? 'Editar tipo de ausencia' : 'Nuevo tipo de ausencia', deactivate: 'No puedes eliminar este tipo de ausencia', 'full-detail': 'Ficha completa' }; const confirm = () => { if (requiresReason && !reason.trim()) return; if (modal.kind === 'cancel') onAction(request, 'Cancelada', 'Solicitud cancelada correctamente'); else if (modal.kind === 'reject') onAction(request, 'Rechazada', 'Solicitud rechazada'); else if (modal.kind === 'correction') onAction(request, 'Corrección requerida', 'Se solicitó una corrección al empleado'); else if (modal.kind === 'approve' || modal.kind === 'approve-conflict') onAction(request, 'Aprobada', 'Solicitud aprobada'); else if (modal.kind === 'adjust') { onClose(); flash(`Saldo ajustado a ${18 + Number(amount || 0)} días`) } else { onClose(); flash(modal.kind === 'deactivate' ? 'Tipo de ausencia desactivado' : 'Configuración guardada') } }; return <div className="fixed inset-0 z-[60] flex items-center justify-center bg-slate-950/45 p-4" role="presentation"><section role="dialog" aria-modal="true" aria-labelledby="modal-title" className="max-h-[calc(100vh-2rem)] w-full max-w-lg overflow-y-auto rounded-2xl bg-white shadow-2xl"><div className="flex items-start justify-between border-b border-slate-100 px-6 py-5"><div><p className="text-xs font-semibold text-indigo-600">ACCIÓN DE RR. HH.</p><h2 id="modal-title" className="mt-1 text-lg font-semibold tracking-[-.02em] text-slate-950">{titles[modal.kind]}</h2></div><button type="button" onClick={onClose} aria-label="Cerrar modal" className="rounded-lg p-2 text-slate-400 hover:bg-slate-100 hover:text-slate-700"><X size={18} /></button></div><div className="px-6 py-5">{modal.kind === 'discard' ? <p className="text-sm leading-6 text-slate-600">Si sales ahora perderás las modificaciones realizadas en esta solicitud.</p> : modal.kind === 'adjust' ? <AdjustBalance amount={amount} setAmount={setAmount} /> : modal.kind === 'type-config' ? <TypeConfig editing={modal.editing} /> : modal.kind === 'deactivate' ? <div className="rounded-xl border border-amber-100 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><AlertTriangle size={18} className="mb-2 text-amber-600" /><p>Existen 143 solicitudes históricas asociadas. Puedes desactivar el tipo para evitar nuevos registros; el historial no se modificará.</p></div> : modal.kind === 'full-detail' ? <p className="text-sm leading-6 text-slate-600">La ficha completa se abrirá como una vista dedicada al integrar el backend y auditoría documental.</p> : <><RequestContext request={request} />{modal.kind === 'approve-conflict' && <div className="mt-4 flex gap-3 rounded-xl border border-amber-100 bg-amber-50 p-4 text-sm leading-6 text-amber-900"><AlertTriangle size={18} className="mt-1 shrink-0 text-amber-600" /><p>Durante estas fechas ya existen 3 personas del equipo ausentes. Puedes aprobar de todas formas.</p></div>}{requiresReason && <label className="mt-5 block"><span className="text-xs font-semibold text-slate-700">{modal.kind === 'correction' ? '¿Qué debe corregir el empleado?' : 'Motivo'} </span><textarea value={reason} onChange={(event) => setReason(event.target.value)} className={`${inputClass} mt-1.5 h-24 resize-none py-3 ${!reason && 'border-slate-200'}`} placeholder={modal.kind === 'reject' ? 'Ej. La solicitud coincide con el cierre mensual del área.' : modal.kind === 'correction' ? 'Ej. Adjunta el certificado médico correspondiente.' : 'Indica el motivo de la cancelación.'} />{!reason && <p className="mt-1.5 text-[11px] text-slate-400">Este campo es obligatorio.</p>}</label>}</>}</div><div className="flex justify-end gap-2 border-t border-slate-100 px-6 py-4">{modal.kind === 'discard' ? <><button type="button" onClick={onClose} className="rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-600 hover:bg-slate-50">Seguir editando</button><button type="button" onClick={onDiscard} className="rounded-xl bg-rose-600 px-3 py-2.5 text-sm font-semibold text-white hover:bg-rose-700">Salir sin guardar</button></> : <><button type="button" onClick={onClose} className="rounded-xl px-3 py-2.5 text-sm font-semibold text-slate-600 hover:bg-slate-50">Volver</button><button type="button" onClick={confirm} className={`rounded-xl px-3.5 py-2.5 text-sm font-semibold text-white ${['cancel', 'reject'].includes(modal.kind) ? 'bg-rose-600 hover:bg-rose-700' : 'bg-indigo-600 hover:bg-indigo-700'}`}>{modal.kind === 'cancel' ? 'Cancelar solicitud' : modal.kind === 'reject' ? 'Rechazar solicitud' : modal.kind === 'correction' ? 'Solicitar corrección' : modal.kind === 'approve-conflict' ? 'Aprobar de todas formas' : modal.kind === 'adjust' ? 'Aplicar ajuste' : modal.kind === 'deactivate' ? 'Desactivar tipo' : 'Guardar cambios'}</button></>}</div></section></div> }

function RequestContext({ request }) { return <div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold text-slate-800">{request.id}</p><p className="mt-1 text-sm text-slate-600">{request.type} · {formatRange(request.from, request.to)} · {request.days} días</p></div> }
function AdjustBalance({ amount, setAmount }) { const next = 18 + Number(amount || 0); return <><div className="rounded-xl bg-slate-50 p-4"><p className="text-xs font-semibold text-slate-500">Empleado</p><p className="mt-1 text-sm font-semibold text-slate-800">José Ramírez</p><div className="mt-4 grid grid-cols-2 gap-4"><div><p className="text-xs text-slate-500">Saldo actual</p><p className="mt-1 text-lg font-semibold">18 días</p></div><div><p className="text-xs text-slate-500">Nuevo saldo</p><p className={`mt-1 text-lg font-semibold ${next < 0 ? 'text-rose-600' : 'text-indigo-700'}`}>{next} días</p></div></div></div><label className="mt-5 block"><span className="text-xs font-semibold text-slate-700">Cantidad de ajuste</span><input type="number" value={amount} onChange={(event) => setAmount(event.target.value)} className={`${inputClass} mt-1.5`} /><span className="mt-1.5 block text-[11px] text-slate-500">Usa un valor negativo para descontar días.</span></label>{next < 0 && <div className="mt-4 flex gap-3 rounded-xl border border-rose-100 bg-rose-50 p-4 text-sm text-rose-900"><ShieldAlert size={18} className="shrink-0 text-rose-600" />Este ajuste dejará al empleado con saldo negativo. Requiere confirmación explícita.</div>}<label className="mt-5 block"><span className="text-xs font-semibold text-slate-700">Motivo del ajuste</span><textarea className={`${inputClass} mt-1.5 h-20 resize-none py-3`} placeholder="Obligatorio para auditoría" /></label></> }
function TypeConfig({ editing }) { return <><p className="text-sm leading-6 text-slate-600">{editing ? 'Cambiar esta política afectará nuevas solicitudes, pero no modificará solicitudes históricas.' : 'Define una política clara para que las nuevas solicitudes se procesen correctamente.'}</p><div className="mt-5 grid gap-4 sm:grid-cols-2"><Field label="Nombre"><input className={inputClass} defaultValue={editing ? 'Permiso personal' : ''} placeholder="Ej. Licencia especial" /></Field><Field label="Código"><input className={inputClass} defaultValue={editing ? 'PER' : ''} placeholder="Ej. ESP" /></Field></div><div className="mt-5 rounded-xl border border-slate-200 p-4"><p className="text-xs font-semibold text-slate-700">Reglas aplicables</p><div className="mt-3 space-y-3">{['Descuenta saldo', 'Requiere aprobación', 'Permite medio día', 'Requiere documento'].map((label, index) => <label key={label} className="flex items-center justify-between gap-4 text-sm text-slate-600"><span>{label}</span><input type="checkbox" defaultChecked={index < 2} className="h-4 w-4 rounded text-indigo-600" /></label>)}</div></div></> }

function TeamCalendar({ requests, onDetail }) { const days = Array.from({ length: 31 }, (_, index) => index + 1); const events = { 12: { request: requests[0], label: 'José Ramírez', type: 'approved' }, 13: { request: requests[0], label: 'José Ramírez', type: 'approved' }, 14: { request: requests[0], label: 'José Ramírez', type: 'approved' }, 15: { request: requests[2], label: 'Diego Salas', type: 'pending' }, 16: { request: requests[2], label: 'Diego Salas', type: 'pending' } }; return <section className="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 px-5 py-5 sm:px-6"><div><div className="flex items-center gap-2 text-xs font-semibold text-indigo-600"><CalendarDays size={16} />DISPONIBILIDAD DEL EQUIPO</div><h2 className="mt-2 text-xl font-semibold text-slate-950">Octubre 2026</h2></div><div className="flex flex-wrap gap-3 text-xs text-slate-500"><Legend color="bg-emerald-500" label="Aprobada" /><Legend color="bg-amber-500" label="Pendiente" /><Legend color="bg-slate-300" label="Feriado" /></div></div><div className="grid grid-cols-7 border-l border-t border-slate-100">{['Lun', 'Mar', 'Mié', 'Jue', 'Vie', 'Sáb', 'Dom'].map((day) => <div key={day} className="border-b border-r border-slate-100 bg-slate-50 p-2 text-center text-[10px] font-bold uppercase tracking-[.1em] text-slate-400">{day}</div>)}{days.map((day) => <div key={day} className="min-h-24 border-b border-r border-slate-100 p-2 sm:min-h-28"><span className="text-xs font-semibold text-slate-500">{day}</span>{events[day] && <button type="button" onClick={() => onDetail(events[day].request)} className={`mt-2 block w-full truncate rounded-md px-1.5 py-1 text-left text-[10px] font-semibold ${events[day].type === 'approved' ? 'bg-emerald-50 text-emerald-700' : 'bg-amber-50 text-amber-700'}`}><span className="mr-1 inline-block h-1.5 w-1.5 rounded-full bg-current" />{events[day].label}</button>}</div>)}</div></section> }

function Legend({ color, label }) { return <span className="inline-flex items-center gap-1.5"><span className={`h-2 w-2 rounded-full ${color}`} />{label}</span> }

function AbsenceTypes({ role, onModal }) { if (!(role === 'RR. HH.' || role === 'Administrador')) return <EmptyState title="No tienes permisos para esta sección" text="La configuración de tipos de ausencia está disponible para RR. HH. y Administración." />; return <section className="mt-5 overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div className="flex flex-wrap items-center justify-between gap-4 border-b border-slate-100 px-5 py-5 sm:px-6"><div><div className="flex items-center gap-2 text-xs font-semibold text-indigo-600"><Settings2 size={16} />CONFIGURACIÓN</div><h2 className="mt-2 text-xl font-semibold text-slate-950">Tipos de ausencia</h2><p className="mt-1 text-sm text-slate-500">Reglas aplicables a nuevas solicitudes.</p></div><button type="button" onClick={() => onModal({ kind: 'type-config' })} className="inline-flex items-center gap-2 rounded-xl bg-indigo-600 px-3.5 py-2.5 text-sm font-semibold text-white hover:bg-indigo-700"><Plus size={16} />Nuevo tipo</button></div><div className="overflow-x-auto"><div className="min-w-[850px]"><div className="grid grid-cols-[minmax(180px,1.2fr)_80px_115px_120px_120px_90px_120px_44px] gap-4 border-b border-slate-100 bg-slate-50/70 px-5 py-3 text-[10px] font-bold uppercase tracking-[.1em] text-slate-400 sm:px-6"><span>Nombre</span><span>Código</span><span>Saldo</span><span>Aprobación</span><span>Documento</span><span>Estado</span><span>Modificado</span><span /></div>{ABSENCE_TYPES.map((type) => <div key={type.id} className="group grid grid-cols-[minmax(180px,1.2fr)_80px_115px_120px_120px_90px_120px_44px] items-center gap-4 border-b border-slate-100 px-5 py-4 last:border-0 hover:bg-slate-50/80 sm:px-6"><span className="text-sm font-semibold text-slate-800">{type.name}</span><span className="text-xs text-slate-600">{type.code}</span><span className="text-xs text-slate-600">{type.balance}</span><span className="text-xs text-slate-600">{type.approval}</span><span className="text-xs text-slate-600">{type.document}</span><span className="rounded-full bg-emerald-50 px-2 py-1 text-center text-[10px] font-semibold text-emerald-700">{type.state}</span><span className="text-xs text-slate-500">{type.modified}</span><button type="button" onClick={() => onModal({ kind: 'type-config', editing: true, type })} className="rounded-lg p-2 text-slate-400 hover:bg-white hover:text-slate-700 sm:opacity-0 sm:group-hover:opacity-100"><Pencil size={16} /></button></div>)}</div></div><div className="border-t border-slate-100 px-5 py-4 sm:px-6"><button type="button" onClick={() => onModal({ kind: 'deactivate' })} className="text-xs font-semibold text-rose-600 hover:text-rose-700">Gestionar desactivación de tipos usados históricamente</button></div></section> }

function WorkflowBadge({ value }) { const styles = { Borrador: 'bg-slate-100 text-slate-600', Pendiente: 'bg-amber-50 text-amber-700', 'En revisión': 'bg-indigo-50 text-indigo-700', 'Corrección requerida': 'bg-violet-50 text-violet-700', Aprobada: 'bg-emerald-50 text-emerald-700', Rechazada: 'bg-rose-50 text-rose-700', Cancelada: 'bg-slate-100 text-slate-500' }; return <span className={`inline-flex w-fit items-center gap-1.5 rounded-full px-2 py-1 text-[10px] font-semibold ${styles[value] || styles.Borrador}`}><span className="h-1.5 w-1.5 rounded-full bg-current" />{value}</span> }
function Avatar({ initials }) { return <span className="flex h-10 w-10 shrink-0 items-center justify-center rounded-full bg-indigo-100 text-xs font-bold text-indigo-700">{initials}</span> }
function TableSkeleton() { return <div className="space-y-4 p-6">{Array.from({ length: 5 }, (_, index) => <div key={index} className="h-12 animate-pulse rounded-xl bg-slate-100" />)}</div> }
function EmptyState({ title = 'No encontramos solicitudes con estos filtros', text = 'Revisa la búsqueda o elimina alguno de los filtros activos.', onClear }) { return <div className="px-6 py-14 text-center"><span className="mx-auto flex h-11 w-11 items-center justify-center rounded-2xl bg-slate-100 text-slate-400"><Filter size={20} /></span><p className="mt-4 text-sm font-semibold text-slate-800">{title}</p><p className="mt-1 text-sm text-slate-500">{text}</p>{onClear && <button type="button" onClick={onClear} className="mt-4 text-sm font-semibold text-indigo-600">Limpiar filtros</button>}</div> }
function Toast({ children }) { return <div role="status" className="fixed bottom-5 left-1/2 z-[70] flex -translate-x-1/2 items-center gap-2 rounded-xl bg-slate-950 px-4 py-3 text-sm font-medium text-white shadow-2xl"><CheckCircle2 size={17} className="text-emerald-400" />{children}</div> }

const inputClass = 'h-11 w-full rounded-xl border border-slate-200 bg-white px-3.5 text-sm text-slate-900 outline-none transition placeholder:text-slate-300 focus:border-indigo-500 focus:ring-2 focus:ring-indigo-100'
function calculateDays(from, to) { if (!from || !to || to < from) return 0; const start = new Date(`${from}T00:00:00`); const end = new Date(`${to}T00:00:00`); let count = 0; for (let day = start; day <= end; day = new Date(day.getTime() + 86400000)) { if (day.getDay() !== 0 && day.getDay() !== 6) count += 1 } return count }
function validateForm(form, full) { const errors = {}; if (!form.type) errors.type = 'Selecciona un tipo de ausencia.'; if (!form.from) errors.from = 'Indica la fecha inicial.'; if (!form.to) errors.to = 'Indica la fecha final.'; if (form.from && form.to && form.to < form.from) errors.to = 'La fecha final no puede ser anterior a la inicial.'; if (form.type === 'Vacaciones' && calculateDays(form.from, form.to) > 18) errors.to = 'No cuentas con suficientes días disponibles.'; if (full && ['Permiso personal', 'Otro'].includes(form.type) && !form.reason.trim()) errors.reason = 'Indica el motivo de la solicitud.'; if (full && form.type === 'Licencia médica') { if (!form.diagnosis) errors.diagnosis = 'Completa el motivo administrativo.'; if (!form.entity) errors.entity = 'Indica la entidad médica.'; if (!form.certificate) errors.certificate = 'Indica el número de certificado.'; if (!form.attachment) errors.attachment = 'Adjunta el certificado médico.' } return errors }
function formatDate(value) { if (!value) return 'Por definir'; return new Date(`${value}T00:00:00`).toLocaleDateString('es-PE', { day: '2-digit', month: 'short' }) }
function formatRange(from, to) { return from && to ? `${formatDate(from)} — ${formatDate(to)}` : 'Por definir' }
function filterLabel(key) { return { employee: 'Empleado', area: 'Área', type: 'Tipo', status: 'Estado', date: 'Fecha', supervisor: 'Supervisor' }[key] }

createRoot(document.getElementById('root')).render(<App />)
